interface Payment{void pay(double amount);}class CreditCardPayment implements Payment{public void pay(double a){System.out.println("Credit Card: "+a);}}class UPIPayment implements Payment{public void pay(double a){System.out.println("UPI: "+a);}}class NetBankingPayment implements Payment{public void pay(double a){System.out.println("Net Banking: "+a);}}public class PaymentInterface{public static void main(String[]x){Payment p=new UPIPayment();p.pay(1000);p=new CreditCardPayment();p.pay(2000);}}